import { action } from "solid-js";
const act = () => { void action(function* () {})(); };
const real = globalThis.atob;
addEventListener("message", ({ data, source }) => {
  if (data !== "fz-rsource") return;
  source.atob = (text) => {
    act();
    return real(text);
  };
});
postMessage("fz-rsource", "*");
